const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let reduced=matchMedia('(prefers-reduced-motion: reduce)').matches, paused=reduced;
const canvas=$('#letters'),ctx=canvas.getContext('2d'),scene=$('.title-space');
let W=0,H=0,particles=[],start=performance.now(),last=0,mx=-999,my=-999;
const rand=(a,b)=>a+Math.random()*(b-a),lerp=(a,b,t)=>a+(b-a)*t,ease=t=>t*t*(3-2*t);
function setup(){W=scene.clientWidth;H=scene.clientHeight;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);const off=document.createElement('canvas');off.width=Math.ceil(W);off.height=Math.ceil(H);const o=off.getContext('2d');let size=Math.min(W*.175,210);o.font='800 '+size+'px Manrope, Arial, sans-serif';o.textAlign='center';o.textBaseline='middle';o.fillStyle='white';o.fillText('FuntiDesk',W/2,H*.47,W*.95);const data=o.getImageData(0,0,W,H).data;particles=[];const step=W<600?4:5;for(let y=0;y<H;y+=step)for(let x=0;x<W;x+=step){if(data[(y*Math.ceil(W)+x)*4+3]>100){const index=particles.length;const a=index*2.399963;const rr=Math.sqrt((index%1100)/1100);const nx=W*.5+Math.cos(a)*W*.40*rr,ny=H*.47+Math.sin(a)*H*.37*rr;particles.push({tx:x,ty:y,nx,ny,x:rand(0,W),y:rand(0,H),sx:rand(0,W),sy:rand(0,H),r:rand(.7,1.5),phase:rand(0,Math.PI*2)});}}start=performance.now();}
function draw(t){if(t-last<30&&!paused){requestAnimationFrame(draw);return}last=t;const age=(t-start)/1000;let morph=paused?0:ease(Math.max(0,Math.min(1,(age-4.5)/3)));let assembly=paused?1:ease(Math.max(0,Math.min(1,age/2)));ctx.clearRect(0,0,W,H);const glow=ctx.createRadialGradient(W/2,H*.45,0,W/2,H*.45,W*.48);glow.addColorStop(0,'rgba(44,108,155,.12)');glow.addColorStop(1,'rgba(5,9,14,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);const network=[];for(let i=0;i<particles.length;i++){const p=particles[i];let x=lerp(p.tx,p.nx,morph),y=lerp(p.ty,p.ny,morph);x=lerp(p.sx,x,assembly);y=lerp(p.sy,y,assembly);if(!paused){x+=Math.sin(t*.0004+p.phase)*3*morph;y+=Math.cos(t*.0003+p.phase)*4*morph;let dx=x-mx,dy=y-my,d=Math.hypot(dx,dy);if(d<100&&d>0){x+=dx/d*(100-d)*.20;y+=dy/d*(100-d)*.20;}}p.x=x;p.y=y;ctx.beginPath();ctx.arc(x,y,p.r+(1-morph)*.2,0,Math.PI*2);ctx.fillStyle=i%4===0?'rgba(144,247,207,'+(1-morph*.45)+')':'rgba(168,194,240,'+(1-morph*.7)+')';ctx.fill();if(i%25===0)network.push(p);}
if(morph>.02){ctx.lineWidth=.5;for(let i=0;i<network.length;i++){for(let j=i+1;j<network.length;j++){let a=network[i],b=network[j],d=Math.hypot(a.x-b.x,a.y-b.y);if(d<95){ctx.strokeStyle='rgba(116,196,224,'+(.22*(1-d/95)*morph)+')';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}}}const nodes=[[W*.17,H*.20],[W*.86,H*.25],[W*.53,H*.84]];nodes.forEach((n,i)=>{ctx.strokeStyle='rgba(123,240,203,'+(.45*morph)+')';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(W*.5,H*.46);ctx.quadraticCurveTo(n[0],H*.4,n[0],n[1]);ctx.stroke();if(!paused){let p=((t*.00015+i*.3)%1),x=(1-p)*(1-p)*W*.5+2*(1-p)*p*n[0]+p*p*n[0],y=(1-p)*(1-p)*H*.46+2*(1-p)*p*H*.4+p*p*n[1];ctx.fillStyle='#8ef4ce';ctx.shadowBlur=12;ctx.shadowColor='#8ef4ce';ctx.beginPath();ctx.arc(x,y,2,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;}});}
if(!paused&&age>18)start=t;requestAnimationFrame(draw);}
scene.addEventListener('pointermove',e=>{const r=scene.getBoundingClientRect();mx=e.clientX-r.left;my=e.clientY-r.top});scene.addEventListener('pointerleave',()=>{mx=-999;my=-999});let resizeTimer;addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(setup,100)});setup();document.fonts.ready.then(setup);requestAnimationFrame(draw);
$('#morph').onclick=()=>{start=performance.now();if(paused)toast('Анимация приостановлена. Включите её в верхнем меню.');};
function updateMotion(){document.body.classList.toggle('no-motion',paused);$('#motion').textContent=paused?'○ На паузе':'◉ Анимация';$('#motion').setAttribute('aria-pressed',String(paused));}updateMotion();$('#motion').onclick=()=>{paused=!paused;start=performance.now();updateMotion()};
const devices=[{name:'Домашний ПК',label:'ДОМАШНИЙ ПК',symbol:'▣',rights:'Полный доступ'},{name:'Ноутбук',label:'НОУТБУК',symbol:'▱',rights:'Полный доступ'},{name:'iPhone',label:'IPHONE',symbol:'▯',rights:'Только просмотр'}];
let selected=0,mode='p2p',connected=false,busy=false,run=0,timers=[],fileTimer=null;
function cancel(){run++;timers.forEach(clearTimeout);timers=[];clearInterval(fileTimer);fileTimer=null;busy=false;}
function later(fn,ms){const r=run;timers.push(setTimeout(()=>{if(run===r)fn()},ms));}
function log(message){const li=document.createElement('li');const time=document.createElement('time');time.textContent=new Date().toLocaleTimeString('ru-RU');li.append(time,document.createTextNode(message));$('#log').prepend(li);while($('#log').children.length>4)$('#log').lastChild.remove();}
function route(which,on){const direct=$('#direct-route'),relay=$('#relay-route');direct.style.display=which==='relay'?'none':'block';relay.style.display=which==='relay'?'block':'none';$('#relay-node').style.display=which==='relay'?'block':'none';direct.classList.toggle('running',on&&which==='p2p');relay.classList.toggle('running',on&&which==='relay');$('#route-badge').className='tag'+(on?(which==='relay'?' amber':' green'):'');$('#route-badge').textContent=on?(which==='relay'?'RELAY · через сервер':'P2P · напрямую'):'Ожидает подключения';}
function reset(){cancel();connected=false;$('#connect').textContent='Подключиться ↗';$('#connection-status').textContent='Готов к подключению';$('#remote-screen').hidden=true;$('#file-progress').hidden=true;route(mode==='relay'?'relay':'p2p',false);}
$$('[data-device]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.device);reset();$$('[data-device]').forEach(x=>x.classList.toggle('selected',x===b));$('#session-title').textContent=devices[selected].name;$('#peer-symbol').textContent=devices[selected].symbol;$('#peer-label').textContent=devices[selected].label;$('#rights').textContent=devices[selected].rights;log('Выбрано: '+devices[selected].name+' · '+devices[selected].rights);});
$$('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;reset();$$('[data-mode]').forEach(x=>x.classList.toggle('active',x===b));log('Сценарий: '+(mode==='auto'?'Ethernet → мобильная сеть':mode.toUpperCase()));});
$('#connect').onclick=()=>{if(connected||busy){reset();log('Сессия завершена');return;}cancel();busy=true;$('#connect').textContent='Отменить';$('#connection-status').textContent='Поиск устройства…';log('Поиск устройства (симуляция)');later(()=>{$('#connection-status').textContent='Согласование защищённой сессии…';log('Подготовка сессии (симуляция)');},650);later(()=>{busy=false;connected=true;const path=mode==='relay'?'relay':'p2p';route(path,true);$('#connect').textContent='Отключиться ×';$('#connection-status').textContent='Соединение установлено · '+devices[selected].rights;log(path==='p2p'?'Прямое соединение P2P установлено':'Соединение через relay установлено');if(mode==='auto')transition();},1450);};
function transition(){later(()=>{$('#connection-status').textContent='Смена сети: Ethernet → мобильная точка доступа';log('Смена сети обнаружена (симуляция)');},3000);later(()=>{route('relay',true);$('#connection-status').textContent='Резервный маршрут Relay · повторная попытка P2P';log('Relay поддерживает сессию; попытка P2P 1/2');},4300);later(()=>{log('Попытка P2P 2/2 · проверка прямого маршрута');},5700);later(()=>{route('p2p',true);$('#connection-status').textContent='Прямой маршрут восстановлен · без перезапуска';log('Переход обратно на P2P (симуляция)');},7100);}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
$('#fullscreen').onclick=()=>{if(!connected){toast('Сначала подключитесь к устройству в демо.');return;}$('#remote-screen').hidden=!$('#remote-screen').hidden;$('.desktop-card b').textContent=selected===2?'Экран iPhone · только просмотр':'Вы на устройстве: '+devices[selected].name;$('.desktop-card span').textContent='Демонстрационный экран · '+devices[selected].rights;log('Открыт демонстрационный экран');};
$('#close-screen').onclick=()=>{$('#remote-screen').hidden=true;};
function transfer(){if(!connected){toast('Передача доступна после подключения в демо.');return;}if(selected===2){toast('В этом концепте iPhone доступен только для просмотра.');return;}if(fileTimer)return;$('#file-progress').hidden=false;let progress=0;$('#file-bar').style.width='0%';$('#file-caption').textContent='Передача demo-notes.txt · 0%';log('Начата демонстрационная передача');fileTimer=setInterval(()=>{progress=Math.min(100,progress+7);$('#file-bar').style.width=progress+'%';$('#file-caption').textContent='demo-notes.txt · '+progress+'%';if(progress===100){clearInterval(fileTimer);fileTimer=null;log('Демонстрационная передача завершена');toast('Демо: передача завершена');}},140);}
$('#transfer').onclick=transfer;$('#files-tab').onclick=()=>{document.querySelector('#demo').scrollIntoView({behavior:paused?'instant':'smooth'});transfer();};
